import React from 'react';
import { FaTimes, FaBars } from 'react-icons/fa';

const Header = ({ hider, isSidebarOpen, setIsSidebarOpen }) => {
  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  return (
    <header className="bg-teal-200 text-teal-800 px-6 py-4 flex justify-between items-center shadow">
      <div className="flex">
          <h1 className="text-4xl font-bold mr-10">Admin Panel</h1>
          <button onClick={toggleSidebar} className="text-3xl">
            {isSidebarOpen ? <FaTimes /> : <FaBars />}
          </button>
      </div>
      <div className="flex items-center">
        <span className="material-icons text-3xl mr-2">account_circle</span>
        <span>{hider.nama || 'Loading...'}</span> {/* Nama user */}
      </div>
    </header>
  );
};

export default Header;
